package cn.lvxu.travel;
import java.time.*;import java.util.*;
public final class SearchMemoriesTest {
 static void ok(boolean value,String name){if(!value)throw new AssertionError(name);}public static void main(String[] args){Trip t=new Trip();t.title="旧杭州旅行";t.city="杭州";t.start="2024-09-12";t.days=2;Trip.Stop stop=new Trip.Stop();stop.name="西湖";stop.note="日落拍照";stop.day=0;stop.cost=5000;stop.tagIds.add("sys-nature");t.stops.add(stop);Trip.Expense expense=new Trip.Expense();expense.name="船票";expense.category="门票";expense.amount=6000;expense.occurredAt="2024-09-12T10:00";t.expenses.add(expense);Trip.Item item=new Trip.Item("相机");item.note="准备电池";t.items.add(item);Trip.Checkin checkin=new Trip.Checkin();checkin.place="断桥";checkin.mood="开心";checkin.time="2024-09-12T18:00";t.checkins.add(checkin);SearchIndex.Query q=new SearchIndex.Query();q.text="拍照";ok(SearchIndex.search(Collections.singletonList(t),q).size()==1,"note is searchable");q.text="";q.tagId="sys-nature";ok(SearchIndex.search(Collections.singletonList(t),q).size()==1,"tag and scope filter");q.tagId="";q.minCost=5500L;ok(SearchIndex.search(Collections.singletonList(t),q).size()==1,"cost filter");List<MemoriesQuery.Memory> memories=MemoriesQuery.forDate(Collections.singletonList(t),LocalDate.of(2026,9,12));ok(memories.size()>=3&&memories.get(0).year==2024,"same day memories");System.out.println("PASS: search and memories");}
}
